  return match ? match[1].trim() : null
}

/**
 * Determines the authorization level for a given token based on the configured
 * basic and override key sets. Override keys take precedence.
 */
function getAuthorizationLevel(token: string): AuthorizationLevel {
  const overrideKeys = getKeys(process.env.DOCS_REVALIDATION_OVERRIDE_KEYS)
  if (overrideKeys.includes(token)) {
    return AuthorizationLevel.Override
  }

  const basicKeys = getKeys(process.env.DOCS_REVALIDATION_KEYS)
  if (basicKeys.includes(token)) {
    return AuthorizationLevel.Basic
  }

  return AuthorizationLevel.Unauthorized
}

